import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

// Library: none — native interpolate/spring

const { fontFamily } = loadFont();



export type AdsManagerProps = Record<string, any>;

const AdsManager: React.FC<AdsManagerProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  headerText = "ADS MANAGER",
  spendLabel = "AMOUNT SPENT",
  purchasesLabel = "PURCHASES",
  roasLabel = "ROAS",
  targetSpend = 2480,
  targetPurchases = 0,
  targetRoas = 0.4,
  legendSpend = "SPEND",
  legendRevenue = "REVENUE"
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timeline
  const entranceDuration = Math.round(fps * 1.5);
  const countingDuration = Math.round(fps * 2.5);

  // 1. Card Entrance
  const cardProgress = interpolate(frame, [0, entranceDuration], [0, 1], {
    easing: Easing.out(Easing.exp),
    extrapolateRight: "clamp",
  });

  const cardOpacity = cardProgress;
  const cardScale = interpolate(cardProgress, [0, 1], [0.95, 1]);
  const cardY = interpolate(cardProgress, [0, 1], [40 * s, 0]);

  // 2. Content Entrances (Text and Layout)
  const contentStart = entranceDuration * 0.3;
  const contentProgress = interpolate(frame, [contentStart, contentStart + fps], [0, 1], {
    easing: Easing.out(Easing.exp),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 3. Main Metric Counter
  const spendStart = entranceDuration * 0.5;
  const spendProgress = interpolate(frame, [spendStart, spendStart + countingDuration], [0, 1], {
    easing: Easing.out(Easing.exp),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const currentSpend = spendProgress * targetSpend;
  const formattedSpend = new Intl.NumberFormat("en-US").format(Math.floor(currentSpend));

  // Velocity-based motion blur for the counting number
  const blurAmount = interpolate(spendProgress, [0, 0.05, 0.8, 1], [0, 20 * s, 2 * s, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.ease
  });

  // 4. Bar Chart Growth
  const barHeights = [0.06, 0.1, 0.15, 0.22, 0.3, 0.38, 0.48, 0.58, 0.68, 0.78, 0.9, 1.0];
  const barEntranceStart = spendStart + fps * 0.5;
  
  // 5. Downward Arrow
  const arrowStart = barEntranceStart + fps * 0.5;
  const arrowProgress = interpolate(frame, [arrowStart, arrowStart + fps * 1.5], [0, 1], {
      easing: Easing.out(Easing.exp),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
  });
  const arrowLength = 400 * s;
  const arrowTipY = arrowProgress * arrowLength;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      
      {/* SVG Filter for true vertical motion blur */}
      <svg style={{ position: "absolute", width: 0, height: 0, pointerEvents: "none" }}>
        <filter id="v-blur" colorInterpolationFilters="sRGB">
          <feGaussianBlur stdDeviation={`0 ${blurAmount}`} />
        </filter>
      </svg>

      <div style={{
        width: 860 * s,
        height: 980 * s,
        borderRadius: 28 * s,
        background: "linear-gradient(145deg, rgba(35, 35, 35, 0.7) 0%, rgba(15, 15, 15, 0.7) 100%)",
        border: `${1 * s}px solid rgba(255, 255, 255, 0.12)`,
        boxShadow: `0 ${40 * s}px ${80 * s}px rgba(0,0,0,0.8), inset 0 ${1 * s}px ${2 * s}px rgba(255,255,255,0.05)`,
        backdropFilter: "blur(30px)",
        WebkitBackdropFilter: "blur(30px)",
        padding: 64 * s,
        display: "flex",
        flexDirection: "column",
        fontFamily,
        opacity: cardOpacity,
        transform: `scale(${cardScale}) translateY(${cardY}px)`,
        color: "#fff",
        position: "relative",
        overflow: "hidden",
        transition: "none"
      }}>
        {/* Header */}
        <div style={{ 
            fontSize: 22 * s, 
            color: "#777", 
            fontWeight: 600, 
            letterSpacing: 2.5 * s, 
            marginBottom: 48 * s,
            opacity: contentProgress,
            transform: `translateY(${(1 - contentProgress) * 10 * s}px)`,
            transition: "none"
        }}>
          {headerText}
        </div>

        {/* Metrics Row */}
        <div style={{ 
            display: "flex", 
            flexDirection: "row", 
            alignItems: "center", 
            marginBottom: 48 * s,
            gap: 40 * s,
            opacity: contentProgress,
            transform: `translateY(${(1 - contentProgress) * 10 * s}px)`,
            transition: "none"
        }}>
           {/* Spend */}
           <div style={{ flex: 1.4, display: "flex", flexDirection: "column", transition: "none" }}>
              <div style={{ fontSize: 18 * s, color: "#aaa", fontWeight: 600, marginBottom: 16 * s, letterSpacing: 1 * s, transition: "none" }}>{spendLabel}</div>
              <div style={{
                 fontSize: 90 * s,
                 color: "#fff",
                 fontWeight: 700,
                 fontVariantNumeric: "tabular-nums",
                 letterSpacing: -3 * s,
                 lineHeight: 1,
                 filter: "url(#v-blur)",
                 transform: "translateZ(0)",
                 transition: "none"
              }}>${formattedSpend}</div>
           </div>

           {/* Divider */}
           <div style={{ width: 1 * s, height: 90 * s, backgroundColor: "rgba(255,255,255,0.08)", transition: "none" }} />

           {/* Purchases */}
           <div style={{ flex: 1, display: "flex", flexDirection: "column", transition: "none" }}>
              <div style={{ fontSize: 18 * s, color: "#aaa", fontWeight: 600, marginBottom: 16 * s, letterSpacing: 1 * s, transition: "none" }}>{purchasesLabel}</div>
              <div style={{ 
                  fontSize: 70 * s, 
                  color: "#555", 
                  fontWeight: 600, 
                  fontVariantNumeric: "tabular-nums", 
                  letterSpacing: -2 * s,
                  lineHeight: 1,
                  transition: "none"
              }}>{targetPurchases}</div>
           </div>

           {/* Divider */}
           <div style={{ width: 1 * s, height: 90 * s, backgroundColor: "rgba(255,255,255,0.08)", transition: "none" }} />

           {/* ROAS */}
           <div style={{ flex: 1, display: "flex", flexDirection: "column", transition: "none" }}>
              <div style={{ fontSize: 18 * s, color: "#aaa", fontWeight: 600, marginBottom: 16 * s, letterSpacing: 1 * s, transition: "none" }}>{roasLabel}</div>
              <div style={{ 
                  fontSize: 70 * s, 
                  color: "#555", 
                  fontWeight: 600, 
                  fontVariantNumeric: "tabular-nums", 
                  letterSpacing: -2 * s,
                  lineHeight: 1,
                  transition: "none"
              }}>{targetRoas.toFixed(1)}x</div>
           </div>
        </div>

        {/* Horizontal Divider */}
        <div style={{ 
            width: "100%", 
            height: 1 * s, 
            backgroundColor: "rgba(255,255,255,0.08)", 
            marginBottom: 48 * s,
            opacity: contentProgress,
            transition: "none"
        }} />

        {/* Chart Area */}
        <div style={{ flex: 1, display: "flex", flexDirection: "row", position: "relative", transition: "none" }}>
            {/* Legend */}
            <div style={{ 
                position: "absolute", 
                top: 0, 
                left: 0, 
                display: "flex", 
                flexDirection: "column", 
                gap: 20 * s,
                opacity: contentProgress,
                transition: "none"
            }}>
                <div style={{ display: "flex", alignItems: "center", gap: 16 * s, transition: "none" }}>
                    <div style={{ width: 18 * s, height: 18 * s, backgroundColor: "#ddd", borderRadius: 2 * s, transition: "none" }} />
                    <div style={{ fontSize: 18 * s, color: "#aaa", fontWeight: 600, letterSpacing: 1.5 * s, transition: "none" }}>{legendSpend}</div>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 16 * s, transition: "none" }}>
                    <div style={{ width: 18 * s, height: 18 * s, backgroundColor: "#333", borderRadius: 2 * s, transition: "none" }} />
                    <div style={{ fontSize: 18 * s, color: "#555", fontWeight: 600, letterSpacing: 1.5 * s, transition: "none" }}>{legendRevenue}</div>
                </div>
            </div>

            {/* Bars Container */}
            <div style={{ 
                position: "absolute", 
                bottom: 0, 
                left: 0, 
                width: 640 * s, 
                height: 400 * s, 
                display: "flex", 
                alignItems: "flex-end", 
                justifyContent: "space-between",
                transition: "none"
            }}>
                {barHeights.map((h, i) => {
                    const barStart = barEntranceStart + i * (fps * 0.08);
                    const barProgress = interpolate(frame, [barStart, barStart + fps * 1.5], [0, 1], {
                        easing: Easing.out(Easing.exp),
                        extrapolateLeft: "clamp",
                        extrapolateRight: "clamp"
                    });
                    
                    const barHeight = h * 380 * s * barProgress;
                    
                    return (
                        <div key={`bar-group-${i}`} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 * s, transition: "none" }}>
                            {/* Main Bar (Spend) */}
                            <div style={{
                                width: 32 * s,
                                height: barHeight,
                                background: "linear-gradient(180deg, #d4d4d4 0%, #444 100%)",
                                borderRadius: `${2 * s}px ${2 * s}px 0 0`,
                                opacity: barProgress > 0 ? 1 : 0, // Fully hidden before entrance
                                transformOrigin: "bottom",
                                transform: `scaleY(${barProgress > 0 ? 1 : 0})`,
                                transition: "none"
                            }} />
                            {/* Revenue Baseline Indicator */}
                            <div style={{
                                width: 32 * s,
                                height: 6 * s,
                                backgroundColor: "#333",
                                opacity: contentProgress,
                                borderRadius: 1 * s,
                                transition: "none"
                            }} />
                        </div>
                    )
                })}
            </div>

            {/* Right Edge Arrow */}
            <div style={{ 
                position: "absolute", 
                bottom: 0, 
                right: 0, 
                width: 40 * s, 
                height: 400 * s,
                display: "flex",
                justifyContent: "center",
                opacity: arrowProgress > 0 ? 1 : 0, // Fully hidden before entrance
                transition: "none"
            }}>
                 <svg width={40 * s} height={400 * s} style={{ overflow: "visible", transition: "none" }}>
                     {/* Line Drawing Downward */}
                     <line 
                        x1={20 * s} 
                        y1={0} 
                        x2={20 * s} 
                        y2={arrowTipY} 
                        stroke="#555" 
                        strokeWidth={3 * s} 
                        strokeLinecap="round"
                        style={{ transition: "none" }}
                     />
                     {/* Arrowhead riding the tip exactly */}
                     <g transform={`translate(${20 * s}, ${arrowTipY})`} style={{ transition: "none" }}>
                         <polyline 
                            points={`${-12 * s},${-12 * s} 0,0 ${12 * s},${-12 * s}`} 
                            fill="none" 
                            stroke="#555" 
                            strokeWidth={3 * s} 
                            strokeLinecap="round" 
                            strokeLinejoin="round"
                            style={{ transition: "none" }}
                         />
                     </g>
                 </svg>
            </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default AdsManager;